export default "/*\n * outbound.css — domain residue for com.ikenga.outbound.\n *\n * Kit classes (.frame*, .ip-*, .dense-row*, .badge, .chip, .tag, .btn*,\n * .nav-group*, .nav-item*, .atelier-state.*, .ob-actions*, .cmdk) come from\n * @ikenga/tokens app-kit and are NEVER redefined here. Only these domain-local\n * classes belong in this file:\n *\n *   .nl-*            Newsletter/inner-tab layout anatomy\n *   .ob-header       Channel header block\n *   .ob-chip.*       Channel identity + status chips (provider-identity hues)\n *   .ob-filter-chip  Sent-view filter chips (workspace-tinted)\n *   .ob-seq-*        Sequences sub-state anatomy\n *   .cal-pill.*      Calendar schedule pill states\n *   Provider hues are FIXED constants (not workspace-tint tokens).\n *\n * Inject order (app.js): tokens-css → app-kit-css → outbound-css.\n * This file is regenerated by `scripts/build.mjs` from this source file.\n */\n\n/* ─── Channel header ────────────────────────────────────────────────────────── */\n\n.ob-header {\n  padding: 1rem 1.25rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  flex-shrink: 0;\n}\n\n.ob-header h1 {\n  font: var(--text-h3, 600 16px/1.3 var(--font-sans, system-ui));\n  color: var(--fg);\n  margin: 0 0 0.125rem;\n}\n\n.ob-header .sub {\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  margin: 0;\n}\n\n.ob-header .meta {\n  font-size: 0.7rem;\n  color: var(--fg-faint, var(--fg-muted));\n  margin-top: 0.125rem;\n}\n\n/* ─── Inner-tab strip (.nl-inner-tabs = .pane-inner-tabs canonical) ─────────── */\n\n.nl-inner-tabs {\n  display: flex;\n  gap: 0;\n  padding: 0 0.75rem;\n  border-bottom: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  flex-shrink: 0;\n}\n\n.nl-inner-tabs button {\n  background: none;\n  border: none;\n  border-bottom: 2px solid transparent;\n  cursor: pointer;\n  color: var(--fg-muted);\n  font: 0.75rem/1.4 var(--font-sans, system-ui);\n  font-weight: 500;\n  padding: 0.5rem 0.625rem;\n  margin-bottom: -1px;\n  transition: color 0.15s, border-color 0.15s;\n}\n\n.nl-inner-tabs button.is-on {\n  color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n  border-bottom-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.nl-inner-tabs button:hover:not(.is-on) {\n  color: var(--fg);\n}\n\n.nl-tab-count {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 1.1rem;\n  height: 1.1rem;\n  padding: 0 0.25rem;\n  border-radius: 0.55rem;\n  background: var(--tint-outbox-bg, var(--bg-alt));\n  color: var(--tint-outbox-fg, var(--fg-muted));\n  font-size: 0.65rem;\n  font-weight: 600;\n  margin-left: 0.25rem;\n  vertical-align: middle;\n}\n\n/* ─── Queue master/detail split (.nl-split) ─────────────────────────────────── */\n\n.nl-split {\n  display: grid;\n  grid-template-columns: 320px 1fr;\n  height: 100%;\n  overflow: hidden;\n}\n\n.nl-master {\n  overflow-y: auto;\n  border-right: 1px solid var(--border-faint);\n  padding: 0.5rem 0;\n}\n\n.nl-master-group-head {\n  padding: 0.5rem 1rem 0.25rem;\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  position: sticky;\n  top: 0;\n  background: var(--bg-base);\n  z-index: 1;\n}\n\n.nl-detail {\n  overflow-y: auto;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Queue draft rows */\n.nl-row {\n  display: flex;\n  flex-direction: column;\n  gap: 0.2rem;\n  padding: 0.625rem 1rem;\n  cursor: pointer;\n  border-bottom: 1px solid var(--border-faint);\n  transition: background 0.1s;\n}\n\n.nl-row:hover {\n  background: var(--bg-alt);\n}\n\n.nl-row.is-on {\n  background: var(--bg-alt);\n  border-left: 2px solid var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.nl-row-head {\n  display: flex;\n  align-items: center;\n  gap: 0.375rem;\n  flex-wrap: wrap;\n}\n\n.nl-row-subj {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.nl-row-pre {\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* ─── Channel identity chips (provider-identity hues — FIXED constants) ──────── */\n/* These are intentionally NOT workspace-tint tokens — provider brand colors are\n   permanent across all themes (Resend verdigris, Listmonk amber, SMTP slate-blue,\n   Buffer purple). Same rule as mail/dist/outbound.css chip palette. */\n\n.ob-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.2rem;\n  padding: 0.15rem 0.45rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  white-space: nowrap;\n}\n\n/* Channel identity */\n.ob-chip.channel-resend {\n  background: hsl(174 60% 18%);\n  color: hsl(174 60% 72%);\n}\n\n.ob-chip.channel-listmonk {\n  background: hsl(38 80% 18%);\n  color: hsl(38 80% 72%);\n}\n\n.ob-chip.channel-smtp {\n  background: hsl(220 40% 22%);\n  color: hsl(220 40% 76%);\n}\n\n.ob-chip.channel-buffer {\n  background: hsl(265 50% 22%);\n  color: hsl(265 50% 76%);\n}\n\n/* Status */\n.ob-chip.seq {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n}\n\n.ob-chip.edited {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n  font-style: italic;\n}\n\n.ob-chip.sender {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n}\n\n/* Cold sender — reputational-risk signal */\n.ob-chip.sender.cold {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n  font-weight: 700;\n}\n\n/* Cooling period */\n.ob-chip.cooling {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n}\n\n/* Quality score */\n.ob-chip.quality {\n  background: var(--bg-alt);\n  color: var(--fg);\n  font-variant-numeric: tabular-nums;\n}\n\n.ob-chip.quality.high {\n  background: hsl(142 50% 18%);\n  color: hsl(142 50% 65%);\n}\n\n/* A/B variant indicator */\n.ob-chip.ab {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n  border: 1px solid var(--border-faint);\n}\n\n/* Overdue status — uses --danger */\n.ob-chip.overdue {\n  background: color-mix(in srgb, var(--danger) 15%, transparent);\n  color: var(--danger);\n  font-weight: 700;\n}\n\n/* ─── Sent-view filter chips (.ob-filter-chip) ──────────────────────────────── */\n\n.ob-filter-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.2rem 0.55rem;\n  border-radius: 1rem;\n  font-size: 0.7rem;\n  font-weight: 500;\n  cursor: pointer;\n  border: 1px solid var(--border-faint);\n  background: none;\n  color: var(--fg-muted);\n  transition: background 0.1s, color 0.1s;\n}\n\n.ob-filter-chip:hover {\n  background: var(--bg-alt);\n  color: var(--fg);\n}\n\n.ob-filter-chip.is-on {\n  background: var(--tint-outbox-bg, var(--bg-alt));\n  color: var(--tint-outbox-fg, var(--fg));\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--border-faint)));\n}\n\n/* ─── Calendar grid (.nl-cal-wrap / .nl-cal-week / etc.) ───────────────────── */\n\n.nl-cal-wrap {\n  padding: 0.75rem 1rem;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.nl-cal-week {\n  display: grid;\n  grid-template-columns: repeat(7, 1fr);\n  gap: 0.5rem;\n  min-width: 640px;\n}\n\n.nl-cal-cell {\n  min-height: 5rem;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  padding: 0.375rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.25rem;\n}\n\n.nl-cal-day-num {\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  margin-bottom: 0.125rem;\n}\n\n.nl-cal-day-num.today {\n  color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n/* Calendar pills (.nl-cal-pill = .cal-pill from design) */\n.nl-cal-pill {\n  display: block;\n  padding: 0.2rem 0.4rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 500;\n  background: color-mix(in srgb, var(--tint-outbox-bg, var(--bg-alt)) 40%, transparent);\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  cursor: pointer;\n}\n\n.nl-cal-pill:hover {\n  background: var(--tint-outbox-bg, var(--bg-alt));\n}\n\n/* Cooling: amber bg */\n.nl-cal-pill.cool {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n}\n\n/* Investor update type: live green */\n.nl-cal-pill.investor {\n  background: color-mix(in srgb, var(--live, hsl(142 50% 40%)) 20%, transparent);\n  color: var(--live, hsl(142 50% 50%));\n}\n\n/* Sent (past): dim, dashed */\n.nl-cal-pill.sent {\n  background: var(--bg-base);\n  border: 1px dashed var(--border-faint);\n  opacity: 0.7;\n}\n\n/* ─── Sent view (.nl-sent-toolbar / .nl-sent-table) ─────────────────────────── */\n\n.nl-sent-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.625rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  flex-shrink: 0;\n  flex-wrap: wrap;\n}\n\n.nl-view-toggle {\n  display: flex;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  overflow: hidden;\n  margin-left: auto;\n}\n\n.nl-view-toggle button {\n  background: none;\n  border: none;\n  padding: 0.25rem 0.625rem;\n  font-size: 0.7rem;\n  font-weight: 500;\n  color: var(--fg-muted);\n  cursor: pointer;\n  transition: background 0.1s, color 0.1s;\n}\n\n.nl-view-toggle button.is-on {\n  background: var(--bg-alt);\n  color: var(--fg);\n}\n\n.nl-sent-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 0.75rem 1rem;\n}\n\n.nl-sent-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.75rem;\n}\n\n.nl-sent-table th {\n  text-align: left;\n  padding: 0.375rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  color: var(--fg-muted);\n  font-weight: 600;\n  font-size: 0.7rem;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n  white-space: nowrap;\n}\n\n.nl-sent-table td {\n  padding: 0.5rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  color: var(--fg);\n  vertical-align: middle;\n}\n\n.nl-sent-table td.num {\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  color: var(--fg);\n}\n\n.nl-sent-table td.pct {\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  color: var(--fg-muted);\n}\n\n.nl-sent-table td.meta {\n  color: var(--fg-muted);\n  font-size: 0.7rem;\n}\n\n/* ─── Newsletter detail / quality panel ───────────────────────────────────────── */\n\n.nl-quality-wrap {\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.nl-quality-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.3rem 0;\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.nl-quality-row:last-child {\n  border-bottom: none;\n}\n\n.nl-quality-row .label {\n  color: var(--fg-muted);\n}\n\n.nl-quality-row .score {\n  font-weight: 600;\n  color: var(--fg);\n  font-variant-numeric: tabular-nums;\n}\n\n.nl-quality-row .score.pass {\n  color: hsl(142 50% 50%);\n}\n\n.nl-quality-row .score.fail {\n  color: var(--danger);\n}\n\n/* ─── Sequences sub-state (.ob-seq-*) ────────────────────────────────────────── */\n\n.ob-seq-list {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.ob-seq-row {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  align-items: start;\n  gap: 0.5rem;\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n  cursor: pointer;\n  transition: background 0.1s;\n}\n\n.ob-seq-row:hover {\n  background: var(--bg-alt);\n}\n\n.ob-seq-row.is-on {\n  background: var(--bg-alt);\n  border-left: 2px solid var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.ob-seq-name {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.ob-seq-meta {\n  font-size: 0.7rem;\n  color: var(--fg-muted);\n  margin-top: 0.125rem;\n}\n\n.ob-seq-stats {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 0.125rem;\n}\n\n.ob-seq-step {\n  font-size: 0.7rem;\n  color: var(--fg-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.ob-seq-detail {\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  padding: 1rem;\n}\n\n/* ─── Pane-level state wrappers (.atelier-state.*) ───────────────────────────── */\n/* Classes from app-kit — only sizing overrides here if needed */\n\n.atelier-state {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 0.75rem;\n  padding: 2rem;\n  text-align: center;\n  min-height: 180px;\n}\n\n/* ─── Outbound send detail pane (approve-gate shape) ─────────────────────────── */\n/* Reuses .ip-head / .ip-meta-row / .ip-body from app-kit; only the container\n   query target is domain-local. */\n\n.ob-detail-wrap {\n  container-type: inline-size;\n  container-name: ob-detail;\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n/* ─── Cooling-period send block ───────────────────────────────────────────────── */\n\n.ob-cooling-block {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.5rem 0.75rem;\n  background: hsl(38 80% 18%);\n  border-radius: 0.375rem;\n  font-size: 0.75rem;\n  color: var(--achievement, hsl(38 80% 62%));\n  margin: 0.5rem 0;\n}\n\n.ob-cooling-block .timer {\n  font-variant-numeric: tabular-nums;\n  font-weight: 600;\n}\n\n/* ─── A/B variant selector ────────────────────────────────────────────────────── */\n\n.ob-ab-selector {\n  display: flex;\n  gap: 0.5rem;\n  padding: 0.5rem 0;\n}\n\n.ob-ab-btn {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 0.2rem;\n  padding: 0.5rem 0.75rem;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  background: none;\n  cursor: pointer;\n  text-align: left;\n  transition: border-color 0.1s, background 0.1s;\n}\n\n.ob-ab-btn.is-on {\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n  background: var(--tint-outbox-bg, var(--bg-alt));\n}\n\n.ob-ab-label {\n  font-size: 0.7rem;\n  font-weight: 700;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n\n.ob-ab-subject {\n  font-size: 0.775rem;\n  font-weight: 500;\n  color: var(--fg);\n}\n\n/* ─── Social platform badge ───────────────────────────────────────────────────── */\n\n.ob-platform-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.15rem 0.45rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.ob-platform-badge.linkedin {\n  background: hsl(210 80% 20%);\n  color: hsl(210 80% 72%);\n}\n\n.ob-platform-badge.twitter,\n.ob-platform-badge.x {\n  background: hsl(0 0% 15%);\n  color: hsl(0 0% 80%);\n}\n\n.ob-platform-badge.instagram {\n  background: hsl(320 60% 20%);\n  color: hsl(320 60% 72%);\n}\n\n.ob-platform-badge.bluesky,\n.ob-platform-badge.bsky {\n  background: color-mix(in srgb, var(--primary) 18%, transparent);\n  color: var(--primary);\n}\n\n/* ─── Reply-intelligence panel (email queue detail) ─────────────────────────── */\n/* Ported from design atelier-outbound-email.html §§B/C (.ri-panel / .ri-grid).\n   Eight cells: Tenant / Last-touch / Health / Sequence (top); Catalog /\n   Open-balance / Owner / Risk (bottom). Surfaced from CRM + tenants when\n   available; collapses to an \"unknown sender\" row otherwise. */\n\n.ri-panel {\n  background: var(--bg-sunken);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  padding: var(--space-3);\n  margin: var(--space-4) var(--space-5) 0;\n}\n\n.ri-panel-head {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  margin-bottom: var(--space-3);\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  letter-spacing: 0.06em;\n  color: var(--fg-faint);\n  text-transform: uppercase;\n}\n\n.ri-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: var(--space-3);\n}\n\n@container ob-detail (max-width: 760px) {\n  .ri-grid { grid-template-columns: repeat(2, 1fr); }\n}\n\n.ri-cell {\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-sm);\n  padding: var(--space-2) var(--space-3);\n}\n\n.ri-cell-label {\n  font-family: var(--font-mono);\n  font-size: 9.5px;\n  letter-spacing: 0.06em;\n  color: var(--fg-faint);\n  text-transform: uppercase;\n  margin-bottom: 4px;\n}\n\n.ri-cell-value {\n  font-size: var(--text-body);\n  color: var(--fg);\n  font-weight: 500;\n}\n\n.ri-cell-sub {\n  font-size: 11px;\n  color: var(--fg-muted);\n  margin-top: 2px;\n}\n\n/* Unknown-sender collapse (no CRM record) */\n.ri-empty {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  font-size: 0.8125rem;\n  color: var(--fg-muted);\n}\n\n.ri-empty b { color: var(--fg); }\n\n/* ─── Inline reject reason panel (all queues) ───────────────────────────────── */\n/* Ported from design newsletter §D / email §D / social §D (.nl-reject). Five\n   canned reason chips + freetext; reasons feed the writer-agent dataset. */\n\n.ob-reject {\n  background: color-mix(in srgb, var(--danger) 10%, var(--bg-surface));\n  border-top: 1px solid color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n  border-bottom: 1px solid color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n  padding: var(--space-3) var(--space-4);\n  display: grid;\n  gap: var(--space-2);\n}\n\n.ob-reject-label {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--danger);\n}\n\n.ob-reject-canned {\n  display: flex;\n  gap: 4px;\n  flex-wrap: wrap;\n}\n\n.ob-reject-canned button {\n  background: var(--bg-base);\n  border: 1px dashed color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n  color: var(--fg-muted);\n  border-radius: var(--radius-pill, 1rem);\n  padding: 2px 8px;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.04em;\n  cursor: pointer;\n  transition: color 0.1s, border-color 0.1s;\n}\n\n.ob-reject-canned button:hover,\n.ob-reject-canned button.is-on {\n  color: var(--danger);\n  border-color: var(--danger);\n}\n\n.ob-reject input {\n  background: var(--bg-base);\n  border: 1px solid color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n  border-radius: var(--radius-sm);\n  padding: 6px var(--space-2);\n  color: var(--fg);\n  font: inherit;\n  font-size: 0.8125rem;\n  outline: none;\n}\n\n.ob-reject input:focus { border-color: var(--danger); }\n\n.ob-reject-row {\n  display: flex;\n  gap: var(--space-2);\n  justify-content: flex-end;\n}\n\n/* ─── Secondary action footer (ob-actions-secondary) ────────────────────────── */\n/* Ported from design newsletter §B (.nl-actions): ↩ Back · ⌘ Send to chat ·\n   ⏭ Skip month · ✕ Reject · [spacer] · scheduled meta · 💾 Save · ✓ Approve. */\n\n.ob-actions-secondary {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  flex-wrap: wrap;\n  row-gap: var(--space-2);\n  padding: var(--space-2) var(--space-4);\n  border-top: 1px solid var(--border-faint);\n}\n\n.ob-actions-secondary .ob-act-meta {\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  color: var(--fg-faint);\n  letter-spacing: 0.04em;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  min-width: 0;\n  flex-shrink: 1;\n}\n\n.ob-actions-secondary .ob-act-spacer { flex: 1 1 auto; min-width: 0; }\n\n.ob-btn-sm {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 10px;\n  border-radius: var(--radius-sm);\n  border: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  color: var(--fg);\n  font-size: 0.7rem;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: background 0.1s, color 0.1s, border-color 0.1s;\n}\n\n.ob-btn-sm:hover { background: var(--bg-alt); }\n\n.ob-btn-sm.is-danger {\n  color: var(--danger);\n  border-color: color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n}\n\n.ob-btn-sm.is-primary {\n  color: var(--tint-outbox-fg, var(--fg));\n  border-color: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 35%, var(--border-faint));\n  background: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 8%, var(--bg-base));\n}\n\n/* ─── 10-second undo bar (folded approve-gate, WP-04) ────────────────────────── */\n/* Replaces the primary-action row while a commit is armed: NO DB write happens\n   during the window; the row commits on countdown, or the Undo button aborts. */\n\n.ob-undo-bar {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  padding: var(--space-3) var(--space-4);\n  border-top: 1px solid color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 30%, var(--border-faint));\n  background: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 10%, var(--bg-surface));\n}\n\n.ob-undo-bar .ob-undo-text {\n  font-size: 0.8125rem;\n  color: var(--fg);\n  flex: 1 1 auto;\n  min-width: 0;\n}\n\n.ob-undo-bar .ob-undo-text strong {\n  font-family: var(--font-mono);\n  color: var(--tint-outbox-fg, var(--fg));\n}\n\n/* ─── Edit-in-place panel (folded approve-gate, WP-04) ───────────────────────── */\n/* Patch subject/body before approving — writes via host.paActions.update. */\n\n.ob-edit-panel {\n  background: var(--bg-surface);\n  border-top: 1px solid var(--border-faint);\n  border-bottom: 1px solid var(--border-faint);\n  padding: var(--space-3) var(--space-4);\n  display: grid;\n  gap: var(--space-2);\n}\n\n.ob-edit-label {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--fg-muted);\n}\n\n.ob-edit-field {\n  display: grid;\n  gap: 4px;\n}\n\n.ob-edit-field > span {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.04em;\n  color: var(--fg-faint);\n}\n\n.ob-edit-field input,\n.ob-edit-field textarea {\n  background: var(--bg-base);\n  border: 1px solid var(--border-faint);\n  border-radius: var(--radius-sm);\n  padding: 6px var(--space-2);\n  color: var(--fg);\n  font: inherit;\n  font-size: 0.8125rem;\n  outline: none;\n  resize: vertical;\n}\n\n.ob-edit-field input:focus,\n.ob-edit-field textarea:focus {\n  border-color: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 45%, var(--border-faint));\n}\n\n.ob-edit-row {\n  display: flex;\n  gap: var(--space-2);\n  justify-content: flex-end;\n}\n\n/* ─── Newsletter subject card + body pane ───────────────────────────────────── */\n/* Ported from design newsletter §B (.subj-card / preview body textarea). */\n\n.nl-subj-card {\n  padding: var(--space-3) var(--space-4);\n  border-bottom: 1px solid var(--border-faint);\n  background: var(--bg-surface);\n  display: grid;\n  gap: var(--space-2);\n}\n\n.nl-subj-row {\n  display: grid;\n  grid-template-columns: 80px 1fr;\n  gap: var(--space-2);\n  align-items: center;\n}\n\n.nl-subj-row .lbl {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n  text-align: right;\n}\n\n.nl-subj-row input {\n  width: 100%;\n  background: transparent;\n  border: 0;\n  border-bottom: 1px dashed transparent;\n  padding: 4px var(--space-1);\n  color: var(--fg);\n  font-family: inherit;\n  font-size: var(--text-body);\n  outline: none;\n}\n\n.nl-subj-row input:hover { border-bottom-color: var(--border-soft); }\n.nl-subj-row input:focus { border-bottom-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n.nl-subj-row.alt input { font-style: italic; color: var(--fg-muted); }\n\n.nl-subj-card .pre-row {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  flex-wrap: wrap;\n  font-size: var(--text-caption);\n  color: var(--fg-muted);\n  padding-top: var(--space-1);\n  border-top: 1px dashed var(--border-soft);\n}\n\n.nl-subj-card .pre-row .count {\n  margin-left: auto;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.04em;\n}\n\n.nl-body-pane {\n  padding: var(--space-3) var(--space-4);\n  border-bottom: 1px solid var(--border-faint);\n  display: flex;\n  flex-direction: column;\n  gap: var(--space-2);\n}\n\n.nl-body-pane .lbl {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n}\n\n.nl-body-textarea {\n  width: 100%;\n  box-sizing: border-box;\n  min-height: 160px;\n  resize: vertical;\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-sm);\n  padding: var(--space-3);\n  color: var(--fg);\n  font: inherit;\n  font-size: 0.8125rem;\n  line-height: 1.6;\n}\n\n/* ─── Newsletter 8-cell quality grid ────────────────────────────────────────── */\n/* Ported from design newsletter §B (.quality-grid / .quality-cell). */\n\n.nl-quality-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 0;\n  background: var(--bg-sunken);\n  border-top: 1px solid var(--border-faint);\n  border-bottom: 1px solid var(--border-faint);\n}\n\n@container ob-detail (max-width: 720px) {\n  .nl-quality-grid { grid-template-columns: 1fr 1fr; }\n}\n\n.nl-quality-cell {\n  padding: var(--space-3);\n  border-right: 1px solid var(--border-faint);\n  display: grid;\n  gap: 4px;\n}\n\n.nl-quality-cell:last-child { border-right: 0; }\n\n.nl-quality-cell .qlabel {\n  font-family: var(--font-mono);\n  font-size: 9.5px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n}\n\n.nl-quality-cell .qvalue {\n  font-family: var(--font-display);\n  font-weight: 500;\n  font-size: 18px;\n  line-height: 1.1;\n  color: var(--fg);\n  display: flex;\n  align-items: baseline;\n  gap: 4px;\n}\n\n.nl-quality-cell .qvalue .qsub {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--fg-muted);\n  font-weight: 400;\n  letter-spacing: 0.04em;\n}\n\n.nl-quality-cell.ok .qvalue { color: var(--achievement); }\n.nl-quality-cell.warn .qvalue { color: var(--achievement); }\n.nl-quality-cell.fail .qvalue { color: var(--danger); }\n\n.nl-quality-cell .qbar {\n  height: 4px;\n  background: var(--bg-base);\n  border-radius: 2px;\n  overflow: hidden;\n  border: 1px solid var(--border-soft);\n  margin-top: 2px;\n}\n\n.nl-quality-cell .qbar > div { height: 100%; background: var(--achievement); }\n.nl-quality-cell.warn .qbar > div { background: var(--achievement); }\n.nl-quality-cell.fail .qbar > div { background: var(--danger); }\n\n/* ─── Two-week schedule strip (.nl-cal-grid / .nl-cal-2wk) ───────────────────── */\n/* Ported from design newsletter §E (.cal-week label-column + date numbers +\n   today marker + Lagos tz). Replaces the single Mon–Sun row. */\n\n.nl-cal-2wk {\n  border: 1px solid var(--border-faint);\n  border-radius: var(--radius-md);\n  overflow: hidden;\n}\n\n.nl-cal-tz {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  padding: var(--space-2) var(--space-3);\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.04em;\n  color: var(--fg-faint);\n  background: var(--bg-sunken);\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.nl-cal-grid {\n  display: grid;\n  grid-template-columns: 110px repeat(7, 1fr);\n  border-top: 1px solid var(--border-faint);\n}\n\n.nl-cal-grid:first-of-type { border-top: 0; }\n\n.nl-cal-grid.head { background: var(--bg-sunken); }\n\n.nl-cal-grid .gcell {\n  padding: 8px;\n  border-right: 1px solid var(--border-faint);\n  min-height: 64px;\n  position: relative;\n}\n\n.nl-cal-grid .gcell:last-child { border-right: 0; }\n\n.nl-cal-grid.head .gcell {\n  min-height: 0;\n  text-align: center;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n  padding: var(--space-2) 4px;\n}\n\n.nl-cal-grid .gcell.label {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n  background: var(--bg-sunken);\n}\n\n.nl-cal-grid.head .gcell.is-today,\n.nl-cal-grid .gcell.is-today .g-day-num {\n  color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary)));\n}\n\n.g-day-num {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--fg-muted);\n  margin-bottom: 6px;\n  letter-spacing: 0.04em;\n}\n\n.nl-cal-grid .gcell.is-today .g-day-num { font-weight: 600; }\n\n/* ─── Sequences master/detail step rail (.sq-md / .step-rail / .step-card) ───── */\n/* Ported from design sequences §B. */\n\n.sq-md {\n  display: grid;\n  grid-template-columns: 320px 1fr;\n  height: 100%;\n  overflow: hidden;\n}\n\n.sq-master {\n  border-right: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  overflow-y: auto;\n}\n\n.sq-master-head {\n  padding: var(--space-3) var(--space-3) var(--space-2);\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  letter-spacing: 0.06em;\n  color: var(--fg-faint);\n  text-transform: uppercase;\n  border-bottom: 1px solid var(--border-faint);\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n}\n\n.sq-master-head .ct { color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n\n.sq-row {\n  padding: var(--space-3);\n  border-bottom: 1px solid var(--border-faint);\n  cursor: pointer;\n  transition: background 0.1s;\n}\n\n.sq-row:hover { background: var(--bg-alt); }\n\n.sq-row.is-on {\n  background: var(--bg-alt);\n  border-left: 2px solid var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n  padding-left: calc(var(--space-3) - 2px);\n}\n\n.sq-row-name {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  margin-bottom: 4px;\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n}\n\n.sq-row-time {\n  margin-left: auto;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--fg-faint);\n}\n\n.sq-row-desc {\n  font-size: 11.5px;\n  color: var(--fg-muted);\n  line-height: 1.45;\n  margin-bottom: var(--space-2);\n}\n\n.sq-row-progress {\n  display: flex;\n  gap: 3px;\n  margin-bottom: var(--space-2);\n}\n\n.sq-row-step {\n  flex: 1;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--bg-sunken);\n}\n\n.sq-row-step.is-done { background: var(--live); }\n.sq-row-step.is-active { background: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n\n.sq-row-meta { display: flex; gap: 4px; flex-wrap: wrap; }\n\n.sq-detail {\n  background: var(--bg-base);\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n}\n\n.sq-detail-head {\n  padding: var(--space-4) var(--space-5);\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.sq-detail-head h2 {\n  font-family: var(--font-display);\n  font-size: 18px;\n  line-height: 1.25;\n  margin: 0;\n  color: var(--fg);\n}\n\n.sq-detail-meta {\n  display: flex;\n  gap: var(--space-3);\n  flex-wrap: wrap;\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--fg-muted);\n  margin-top: var(--space-2);\n}\n\n.sq-detail-meta b { color: var(--fg); font-weight: 500; }\n\n.step-rail { padding: var(--space-4) var(--space-5); flex: 1; }\n\n.step-card {\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  padding: var(--space-3);\n  margin-bottom: var(--space-2);\n  position: relative;\n}\n\n.step-card.is-current {\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary)));\n  box-shadow: 0 0 0 1px var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))) inset;\n}\n\n.step-card.is-done { opacity: 0.65; }\n\n.step-card-head {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  margin-bottom: var(--space-2);\n}\n\n.step-num {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  padding: 2px 6px;\n  border-radius: var(--radius-xs);\n  background: var(--bg-sunken);\n  color: var(--fg-muted);\n  border: 1px solid var(--border-soft);\n}\n\n.step-card.is-current .step-num {\n  background: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary)));\n  color: var(--bg-base);\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary)));\n}\n\n.step-card.is-done .step-num { background: var(--live); color: var(--bg-base); border-color: var(--live); }\n\n.step-subj {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n  flex: 1;\n}\n\n.step-card-meta {\n  display: flex;\n  gap: var(--space-3);\n  flex-wrap: wrap;\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  color: var(--fg-faint);\n  margin-bottom: var(--space-2);\n}\n\n.step-card-body {\n  font-size: 0.8125rem;\n  color: var(--fg-muted);\n  line-height: 1.55;\n}\n\n.step-delay {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  padding: var(--space-1) var(--space-3);\n  margin: 0 var(--space-5) 0 calc(var(--space-5) + 8px);\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  color: var(--fg-faint);\n}\n\n.step-delay::before {\n  content: \"\";\n  width: 2px;\n  height: 16px;\n  background: var(--border-soft);\n  display: inline-block;\n}\n\n.sq-footer {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  flex-wrap: wrap;\n  padding: var(--space-3) var(--space-5);\n  background: var(--bg-surface);\n  border-top: 1px solid var(--border-faint);\n}\n\n.sq-footer .actions { margin-left: auto; display: flex; gap: var(--space-2); }\n\n/* ─── Sequences active recipient cohort grid (.rec-grid / .rec-cell) ─────────── */\n/* Ported from design sequences §C. Tile state derived from per-recipient row. */\n\n.rec-diag {\n  display: flex;\n  gap: var(--space-2);\n  flex-wrap: wrap;\n  padding: var(--space-3) var(--space-3) 0;\n}\n\n.rec-diag .chip-warn {\n  background: color-mix(in srgb, var(--achievement) 15%, var(--bg-sunken));\n  color: var(--achievement);\n  border: 1px solid color-mix(in srgb, var(--achievement) 30%, var(--border-faint));\n}\n\n.rec-diag .chip-danger {\n  background: color-mix(in srgb, var(--danger) 15%, var(--bg-sunken));\n  color: var(--danger);\n  border: 1px solid color-mix(in srgb, var(--danger) 30%, var(--border-faint));\n}\n\n.rec-grid {\n  display: grid;\n  grid-template-columns: repeat(8, 1fr);\n  gap: 4px;\n  padding: var(--space-3);\n}\n\n@container ob-detail (max-width: 720px) {\n  .rec-grid { grid-template-columns: repeat(6, 1fr); }\n}\n\n.rec-cell {\n  aspect-ratio: 1;\n  border-radius: var(--radius-xs);\n  background: var(--bg-sunken);\n  border: 1px solid var(--border-soft);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-mono);\n  font-size: 9px;\n  color: var(--fg-faint);\n  cursor: pointer;\n}\n\n.rec-cell.is-step1 {\n  background: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 25%, var(--bg-sunken));\n  color: var(--tint-outbox-fg, var(--primary));\n  border-color: var(--tint-outbox-fg, var(--primary));\n}\n\n.rec-cell.is-step2 {\n  background: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 50%, var(--bg-sunken));\n  color: var(--bg-base);\n  border-color: var(--tint-outbox-fg, var(--primary));\n}\n\n.rec-cell.is-step3 {\n  background: color-mix(in srgb, var(--tint-outbox-fg, var(--primary)) 75%, var(--bg-sunken));\n  color: var(--bg-base);\n  border-color: var(--tint-outbox-fg, var(--primary));\n}\n\n.rec-cell.is-done { background: var(--live); color: var(--bg-base); border-color: var(--live); }\n.rec-cell.is-replied { background: color-mix(in srgb, var(--agent) 60%, var(--bg-sunken)); color: var(--bg-base); border-color: var(--agent); }\n.rec-cell.is-bounced { background: color-mix(in srgb, var(--danger) 50%, var(--bg-sunken)); color: var(--bg-base); border-color: var(--danger); }\n\n.rec-legend {\n  display: flex;\n  gap: var(--space-3);\n  flex-wrap: wrap;\n  padding: var(--space-2) var(--space-3) var(--space-3);\n  font-size: 11px;\n  color: var(--fg-muted);\n}\n\n.rec-legend > span { display: inline-flex; align-items: center; gap: 4px; }\n\n.rec-swatch {\n  width: 10px;\n  height: 10px;\n  border-radius: 2px;\n  border: 1px solid var(--border-soft);\n  display: inline-block;\n}\n\n/* ─── Sequences sent cohort funnel (.funnel) ────────────────────────────────── */\n/* Ported from design sequences §F. */\n\n.sq-sent-grid {\n  display: grid;\n  grid-template-columns: 280px 1fr;\n  height: 100%;\n  overflow: hidden;\n}\n\n.sq-sent-master {\n  border-right: 1px solid var(--border-faint);\n  overflow-y: auto;\n}\n\n.funnel { padding: var(--space-4) var(--space-5); overflow-y: auto; }\n\n.funnel-row {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  margin-bottom: var(--space-2);\n  font-size: 0.8125rem;\n}\n\n.funnel-label {\n  width: 120px;\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n  font-size: 11px;\n}\n\n.funnel-bar {\n  flex: 1;\n  height: 22px;\n  background: var(--bg-sunken);\n  border-radius: var(--radius-xs);\n  overflow: hidden;\n  position: relative;\n}\n\n.funnel-bar > i { display: block; height: 100%; background: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n.funnel-bar > i.is-replied { background: var(--live); }\n.funnel-bar > i.is-bounced { background: var(--danger); }\n\n.funnel-num {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--fg);\n  width: 72px;\n  text-align: right;\n}\n\n.funnel-pct {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--fg-faint);\n  width: 52px;\n  text-align: right;\n}\n\n/* ─── Social per-platform preview editor (.so-editor / .pv-card) ─────────────── */\n/* Ported from design social §B. Editor (left) + stacked previews (right) with\n   per-platform char caps + fan-out rows below. */\n\n.so-editor {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 0;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.so-editor > div {\n  padding: var(--space-4) var(--space-5);\n  overflow-y: auto;\n}\n\n.so-editor > div:first-child { border-right: 1px solid var(--border-faint); }\n\n.so-editor-pane-label {\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  letter-spacing: 0.06em;\n  color: var(--fg-faint);\n  text-transform: uppercase;\n  margin-bottom: var(--space-3);\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n}\n\n.so-text {\n  width: 100%;\n  box-sizing: border-box;\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-sm);\n  padding: var(--space-3);\n  color: var(--fg);\n  font: inherit;\n  font-size: var(--text-body);\n  line-height: 1.55;\n  min-height: 180px;\n  resize: vertical;\n}\n\n.char-rows {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-top: var(--space-2);\n}\n\n.char-row {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  font-size: 11.5px;\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n}\n\n.char-row .clabel { min-width: 120px; }\n.char-row .clabel .over { color: var(--danger); margin-left: 4px; }\n\n.char-bar {\n  flex: 1;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--bg-sunken);\n  overflow: hidden;\n  max-width: 200px;\n}\n\n.char-bar > i { display: block; height: 100%; background: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n.char-bar.is-warn > i { background: var(--achievement); }\n.char-bar.is-bad > i { background: var(--danger); }\n\n.pv-card {\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  padding: var(--space-3);\n  margin-bottom: var(--space-3);\n}\n\n.pv-head {\n  display: flex;\n  gap: var(--space-2);\n  align-items: center;\n  margin-bottom: var(--space-2);\n}\n\n.pv-avatar {\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, var(--tint-outbox-fg, var(--primary)), var(--agent));\n  flex-shrink: 0;\n}\n\n.pv-handle { font-size: 0.8125rem; }\n.pv-handle b { color: var(--fg); }\n.pv-handle span { color: var(--fg-muted); margin-left: 4px; font-size: 11.5px; }\n\n.pv-body {\n  font-size: 0.8125rem;\n  color: var(--fg);\n  line-height: 1.55;\n  white-space: pre-wrap;\n}\n\n.pv-body.is-blocked { color: var(--danger); }\n.pv-tags { color: var(--tint-outbox-fg, var(--tint-fg-active, var(--primary))); }\n\n.pv-stats {\n  display: flex;\n  gap: var(--space-3);\n  margin-top: var(--space-2);\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  color: var(--fg-faint);\n}\n\n.so-fanout {\n  padding: 0 var(--space-5) var(--space-4);\n}\n\n.so-fanout-head {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--fg-faint);\n  padding: var(--space-3) 0 var(--space-2);\n}\n\n.so-fanout-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.75rem;\n}\n\n.so-fanout-table th {\n  text-align: left;\n  padding: 0.3rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  font-family: var(--font-mono);\n  font-size: 0.65rem;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--fg-faint);\n  font-weight: 500;\n}\n\n.so-fanout-table td {\n  padding: 0.4rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  color: var(--fg);\n  vertical-align: middle;\n}\n\n/* Generic platform pills used in fan-out rows (.plat family from design) */\n.plat {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  padding: 2px 6px;\n  border-radius: var(--radius-xs);\n  border: 1px solid;\n  white-space: nowrap;\n}\n\n.plat-li { color: var(--systemic); border-color: color-mix(in srgb, var(--systemic) 45%, transparent); background: color-mix(in srgb, var(--systemic) 10%, transparent); }\n.plat-x { color: var(--fg-muted); border-color: color-mix(in srgb, var(--fg-muted) 35%, transparent); background: color-mix(in srgb, var(--fg-muted) 8%, transparent); }\n.plat-bs { color: var(--primary); border-color: color-mix(in srgb, var(--primary) 45%, transparent); background: color-mix(in srgb, var(--primary) 10%, transparent); }\n.plat-ig { color: var(--achievement); border-color: color-mix(in srgb, var(--achievement) 45%, transparent); background: color-mix(in srgb, var(--achievement) 10%, transparent); }\n\n.chip-ok-sm {\n  display: inline-flex;\n  padding: 0.1rem 0.4rem;\n  border-radius: var(--radius-xs);\n  font-size: 0.65rem;\n  font-weight: 600;\n  background: color-mix(in srgb, var(--live) 15%, var(--bg-sunken));\n  color: var(--live);\n}\n\n.chip-warn-sm {\n  display: inline-flex;\n  padding: 0.1rem 0.4rem;\n  border-radius: var(--radius-xs);\n  font-size: 0.65rem;\n  font-weight: 600;\n  background: color-mix(in srgb, var(--achievement) 15%, var(--bg-sunken));\n  color: var(--achievement);\n}\n\n/* ─── Responsive: nl-split collapses below 720px ────────────────────────────── */\n\n@media (max-width: 720px) {\n  .nl-split,\n  .sq-md,\n  .sq-sent-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .nl-master {\n    display: none;\n  }\n\n  .nl-split.show-master .nl-master {\n    display: block;\n  }\n\n  .nl-split.show-master .nl-detail {\n    display: none;\n  }\n\n  .so-editor {\n    grid-template-columns: 1fr;\n  }\n\n  .so-editor > div:first-child {\n    border-right: 0;\n    border-bottom: 1px solid var(--border-faint);\n  }\n}\n\n/* ─── Reduced motion ─────────────────────────────────────────────────────────── */\n\n@media (prefers-reduced-motion: reduce) {\n  .nl-inner-tabs button,\n  .nl-row,\n  .ob-filter-chip,\n  .nl-cal-pill,\n  .ob-seq-row,\n  .ob-ab-btn,\n  .sq-row,\n  .rec-cell,\n  .ob-btn-sm,\n  .ob-reject-canned button {\n    transition: none;\n  }\n}\n"
